@page "/dispatcher"

@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<div class="container-fluid mt-3">
    <div class="d-flex justify-content-between align-items-center mb-3">
        <h2>🚚 Dispatcher Dashboard</h2>
        <button class="btn btn-success" @onclick="ToggleNewForm">
            @(showNewForm ? "Cancel" : "+ New Shipment")
        </button>
    </div>

    @if (showNewForm)
    {
        <div class="card mb-3">
            <div class="card-body">
                <h5>Create New Shipment</h5>
                <div class="row g-2">
                    <div class="col-md-3">
                        <input class="form-control" placeholder="Tracking Number" @bind="newShipment.TrackingNumber" />
                    </div>
                    <div class="col-md-2">
                        <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                    </div>
                    <div class="col-md-2">
                        <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                    </div>
                    <div class="col-md-2">
                        <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
                    </div>
                    <div class="col-md-3">
                        <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
                    </div>
                    <div class="col-md-2">
                        <label class="form-label small">Shipped Date</label>
                        <input type="date" class="form-control" @bind="newShipment.ShippedDate" />
                    </div>
                    <div class="col-md-2">
                        <label class="form-label small">Est. Delivery</label>
                        <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                    </div>
                    <div class="col-md-2">
                        <select class="form-select" @bind="newShipment.Status">
                            @foreach (var s in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@s">@s</option>
                            }
                        </select>
                    </div>
                    <div class="col-md-2">
                        <button class="btn btn-primary w-100" @onclick="CreateShipment">Create</button>
                    </div>
                </div>
            </div>
        </div>
    }

    <div class="row mb-3 g-2">
        <div class="col-md-4">
            <input class="form-control" placeholder="Search by tracking # or destination..." @bind="searchText" @bind:event="oninput" />
        </div>
        <div class="col-md-3">
            <select class="form-select" @bind="statusFilter">
                <option value="">All Statuses</option>
                @foreach (var s in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@s">@s</option>
                }
            </select>
        </div>
    </div>

    @if (shipments is null)
    {
        <p>Loading...</p>
    }
    else
    {
        <table class="table table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Shipped</th>
                    <th>Est. Delivery</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr @onclick="() => ToggleDetails(s)" style="cursor: pointer;">
                        <td><strong>@s.TrackingNumber</strong></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                    </tr>
                    @if (expandedShipmentId == s.Id)
                    {
                        <tr>
                            <td colspan="6">
                                <div class="card card-body">
                                    <div class="row g-2 align-items-end">
                                        <div class="col-md-3">
                                            <label class="form-label small">Description</label>
                                            <input class="form-control" @bind="s.Description" />
                                        </div>
                                        <div class="col-md-2">
                                            <label class="form-label small">Customer Email</label>
                                            <input class="form-control" @bind="s.CustomerEmail" />
                                        </div>
                                        <div class="col-md-2">
                                            <label class="form-label small">Status</label>
                                            <select class="form-select" @bind="s.Status">
                                                @foreach (var st in Enum.GetValues<ShipmentStatus>())
                                                {
                                                    <option value="@st">@st</option>
                                                }
                                            </select>
                                        </div>
                                        <div class="col-md-2">
                                            <label class="form-label small">Actual Delivery</label>
                                            <input type="date" class="form-control" @bind="s.ActualDelivery" />
                                        </div>
                                        <div class="col-md-2">
                                            <button class="btn btn-primary" @onclick="() => UpdateShipment(s)">Save</button>
                                        </div>
                                    </div>
                                </div>
                            </td>
                        </tr>
                    }
                }
            </tbody>
        </table>
    }
</div>

@code {
    private List<Shipment>? shipments;
    private int? expandedShipmentId;
    private bool showNewForm;
    private Shipment newShipment = new() { ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
    private string searchText = string.Empty;
    private string statusFilter = string.Empty;

    private IEnumerable<Shipment> FilteredShipments =>
        (shipments ?? new()).Where(s =>
            (string.IsNullOrWhiteSpace(searchText) ||
             s.TrackingNumber.Contains(searchText, StringComparison.OrdinalIgnoreCase) ||
             s.Destination.Contains(searchText, StringComparison.OrdinalIgnoreCase)) &&
            (string.IsNullOrWhiteSpace(statusFilter) ||
             s.Status.ToString() == statusFilter));

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ToggleDetails(Shipment s)
    {
        expandedShipmentId = expandedShipmentId == s.Id ? null : s.Id;
    }

    private void ToggleNewForm()
    {
        showNewForm = !showNewForm;
        if (showNewForm)
            newShipment = new() { ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
    }

    private async Task CreateShipment()
    {
        var created = await ShipmentService.CreateShipmentAsync(newShipment);
        shipments?.Add(created);
        showNewForm = false;
    }

    private async Task UpdateShipment(Shipment s)
    {
        await ShipmentService.UpdateShipmentAsync(s);
        expandedShipmentId = null;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-warning text-dark",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-primary",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"

@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<div class="container mt-4" style="max-width: 700px;">
    <h2 class="mb-4">🔍 Track Your Shipment</h2>

    <div class="input-group mb-4">
        <input class="form-control" placeholder="Enter tracking number (e.g. TRK-001)" @bind="trackingNumber" @onkeydown="HandleKeyDown" />
        <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
    </div>

    @if (searched && shipment is null)
    {
        <div class="alert alert-warning">No shipment found for tracking number <strong>@searchedNumber</strong>.</div>
    }

    @if (shipment is not null)
    {
        <div class="card shadow-sm">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h5 class="mb-0">@shipment.TrackingNumber</h5>
                <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
            </div>
            <div class="card-body">
                <div class="mb-4">
                    <div class="d-flex justify-content-between mb-2">
                        <div>
                            <small class="text-muted">Origin</small>
                            <div><strong>@shipment.Origin</strong></div>
                        </div>
                        <div class="text-center align-self-center">→</div>
                        <div class="text-end">
                            <small class="text-muted">Destination</small>
                            <div><strong>@shipment.Destination</strong></div>
                        </div>
                    </div>
                </div>

                <div class="row text-center mb-4">
                    <div class="col">
                        <small class="text-muted">Shipped</small>
                        <div>@shipment.ShippedDate.ToString("MMM dd, yyyy")</div>
                    </div>
                    <div class="col">
                        <small class="text-muted">Est. Delivery</small>
                        <div>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</div>
                    </div>
                    @if (shipment.ActualDelivery.HasValue)
                    {
                        <div class="col">
                            <small class="text-muted">Delivered</small>
                            <div class="text-success fw-bold">@shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</div>
                        </div>
                    }
                </div>

                <p class="text-muted mb-3"><em>@shipment.Description</em></p>

                <!-- Progress Steps -->
                <div class="d-flex justify-content-between position-relative mt-4 mb-2">
                    @{
                        var steps = new[] {
                            ("Pending", ShipmentStatus.Pending),
                            ("Picked Up", ShipmentStatus.PickedUp),
                            ("In Transit", ShipmentStatus.InTransit),
                            ("Out for Delivery", ShipmentStatus.OutForDelivery),
                            ("Delivered", ShipmentStatus.Delivered)
                        };
                        int currentStep = GetProgressStep(shipment.Status);
                    }
                    @for (int i = 0; i < steps.Length; i++)
                    {
                        var (label, _) = steps[i];
                        bool isActive = i <= currentStep;
                        bool isCurrent = i == currentStep;
                        <div class="text-center" style="flex: 1;">
                            <div class="rounded-circle mx-auto d-flex align-items-center justify-content-center @(isActive ? "bg-success text-white" : "bg-light border") @(isCurrent ? "border-3 border-success" : "")"
                                 style="width: 36px; height: 36px; font-size: 0.8rem;">
                                @if (isActive)
                                {
                                    <span>✓</span>
                                }
                                else
                                {
                                    <span>@(i + 1)</span>
                                }
                            </div>
                            <small class="d-block mt-1 @(isActive ? "fw-bold" : "text-muted")">@label</small>
                        </div>
                    }
                </div>

                @if (shipment.Status == ShipmentStatus.Delayed)
                {
                    <div class="alert alert-danger mt-3 mb-0">
                        ⚠️ This shipment is currently <strong>delayed</strong>. Please check back for updates.
                    </div>
                }
            </div>
        </div>
    }
</div>

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private Shipment? shipment;
    private bool searched;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searchedNumber = trackingNumber.Trim();
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        searched = true;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static int GetProgressStep(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 0,
        ShipmentStatus.PickedUp => 1,
        ShipmentStatus.InTransit => 2,
        ShipmentStatus.OutForDelivery => 3,
        ShipmentStatus.Delivered => 4,
        ShipmentStatus.Delayed => 2, // show as in-transit level
        _ => 0
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
